// @vitest-environment jsdom
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { createApp, h, nextTick, type App } from 'vue'
const actions = vi.hoisted(() => ({ local: vi.fn(), remote: vi.fn(), refresh: vi.fn(), revision: vi.fn(), open: vi.fn(), select: vi.fn() }))
vi.mock('../../src/services/agent/websiteRepository', () => ({ onWebsiteRepositoryChanged: () => () => {}, readWebsiteLocalHistory: actions.local, readWebsiteGitHistory: actions.remote, refreshWebsiteGitHistory: actions.refresh, readWebsiteGitHistoryRevision: actions.revision, selectWebsiteRepositoryVersion: actions.select, repositorySourceFor: () => ({ branch: 'main' }) }))
vi.mock('@tauri-apps/plugin-opener', () => ({ openUrl: actions.open }))
import WebsiteRepositoryHistory from '../../src/views/settings/WebsiteRepositoryHistory.vue'
let app: App, root: HTMLElement
const sha = 'a'.repeat(40)
const commit = (id: string, date = '2026-11-02T02:00:00Z') => ({ sha: id, message: '<script>message</script>', author: 'Contributor', date, url: `https://github.com/owner/repo/commit/${id}` })
const close = vi.fn()
const mount = () => { app = createApp({ render: () => h(WebsiteRepositoryHistory, { host: 'chaoxing.com', onClose: close }) }); app.mount(root) }
beforeEach(() => {
  vi.clearAllMocks(); actions.local.mockReset(); actions.remote.mockReset(); actions.refresh.mockReset(); actions.revision.mockImplementation(async (_host, fallback) => fallback)
  actions.local.mockResolvedValue({ hasFork: true, revision: sha, forkId: 'local-1', commits: [
    { id: 'b'.repeat(64), parent: sha, upstreamRevision: sha, createdAt: Date.parse('2026-11-02T03:00:00Z'), kind: 'write', paths: ['SKILL.md'] },
    { id: 'c'.repeat(64), parent: sha, upstreamRevision: sha, createdAt: Date.parse('2026-11-02T01:00:00Z'), kind: 'migrate', paths: ['site-graph.json'] },
  ] })
  actions.remote.mockResolvedValue({ commits: [commit(sha)], hasMore: false })
  root = document.createElement('div'); document.body.append(root); mount()
})
afterEach(() => { app.unmount(); root.remove() })
const dialog = () => document.querySelector<HTMLElement>('[role=dialog]')!
const ready = () => vi.waitFor(() => expect(dialog().querySelectorAll('.history-row')).toHaveLength(3))
const filter = async (source: 'all' | 'github') => {
  dialog().querySelector<HTMLInputElement>(`.history-filter input[value="${source}"]`)!.click()
  await nextTick()
}

describe('unified website timeline', () => {
  it('moves the current-use badge only after switching and can return to the working version', async () => {
    await ready()
    const working = await actions.local()
    const remote = dialog().querySelector<HTMLButtonElement>('.history-remote-commit .history-row')!
    expect(dialog().querySelector('[aria-current="true"] .history-current')?.textContent).toBe('当前使用')
    remote.click()
    await nextTick()
    dialog().querySelector('.is-local .history-row')!.dispatchEvent(new Event('pointerenter'))
    await nextTick()
    expect(remote.getAttribute('aria-expanded')).toBe('true')
    actions.select.mockImplementationOnce(async () => {
      actions.local.mockResolvedValue({ ...working, currentId: sha, workingId: working.commits[0].id, pinned: true })
    })
    dialog().querySelector<HTMLButtonElement>('.history-version-action button')!.click()
    await vi.waitFor(() => expect(remote.getAttribute('aria-current')).toBe('true'))
    expect(actions.select).toHaveBeenLastCalledWith('chaoxing.com', sha)
    actions.select.mockImplementationOnce(async () => { actions.local.mockResolvedValue(working) })
    dialog().querySelector<HTMLButtonElement>('.history-version-status button')!.click()
    await vi.waitFor(() => expect(remote.hasAttribute('aria-current')).toBe(false))
    expect(actions.select).toHaveBeenLastCalledWith('chaoxing.com', null)
  })

  it('shows current work first and preserves parent order in one graph', async () => {
    await ready()
    expect(dialog().querySelectorAll('.history-filter input')).toHaveLength(2)
    expect(dialog().querySelector('.history-filter input[value=local]')).toBeNull()
    expect(dialog().querySelector('.history-filter')?.getAttribute('data-selected-index')).toBe('0')
    expect(dialog().querySelectorAll('.history-list')).toHaveLength(1)
    expect([...dialog().querySelectorAll('.history-entry')].map(row => row.getAttribute('data-source'))).toEqual(['local', 'local', 'github'])
    expect(dialog().querySelector('.is-head')?.textContent).toContain('本地修改')
    expect(dialog().querySelector('.history-remote-commit')?.textContent).toContain('origin/main')
    expect(dialog().textContent).not.toContain('Fork')
    expect(actions.remote).toHaveBeenCalledWith('chaoxing.com', sha, 1)
  })
  it('filters sources without redownloading and removes obsolete hover cards when switching', async () => {
    await ready()
    const first = dialog().querySelector<HTMLButtonElement>('.history-row')!
    first.focus(); await nextTick()
    expect(dialog().querySelector('.history-hover')).not.toBeNull()
    await filter('github')
    expect(dialog().querySelector('.history-filter')?.getAttribute('data-selected-index')).toBe('1')
    expect(dialog().querySelector('.history-hover')).toBeNull()
    expect(dialog().querySelectorAll('.history-row')).toHaveLength(1)
    await filter('all')
    expect(dialog().querySelectorAll('.history-row')).toHaveLength(3)
    expect(actions.remote).toHaveBeenCalledOnce()
  })
  it('refreshes the remote reference without moving the local head, then pages against the new revision', async () => {
    await ready()
    const newer = 'd'.repeat(40)
    let resolve!: (result: unknown) => void
    actions.refresh.mockReturnValueOnce(new Promise(done => { resolve = done }))
    const refresh = dialog().querySelector<HTMLButtonElement>('.history-refresh')!
    refresh.click(); await nextTick()
    expect(refresh.disabled).toBe(true)
    expect(refresh.getAttribute('aria-busy')).toBe('true')
    resolve({ revision: newer, commits: [{ ...commit(newer), parents: [sha] }], hasMore: true })
    await vi.waitFor(() => expect(dialog().querySelectorAll('.history-row')).toHaveLength(4))
    expect(dialog().querySelector('.is-head')?.textContent).toContain('本地修改')
    const remoteHead = [...dialog().querySelectorAll('.history-remote-commit')].find(row => row.textContent?.includes('origin/main'))!
    expect(remoteHead.querySelector('button')!.getAttribute('aria-label')).not.toContain('上游基准')
    expect(refresh.disabled).toBe(false)
    expect(actions.local).toHaveBeenCalledOnce()
    actions.remote.mockResolvedValueOnce({ commits: [], hasMore: false })
    dialog().querySelector<HTMLButtonElement>('.history-more')!.click()
    await vi.waitFor(() => expect(actions.remote).toHaveBeenLastCalledWith('chaoxing.com', newer, 2))
  })
  it('retains loaded history when refresh fails and retries the branch query', async () => {
    await ready()
    actions.refresh.mockRejectedValueOnce(new Error('offline')).mockResolvedValueOnce({ revision: sha, commits: [commit(sha)], hasMore: false })
    dialog().querySelector<HTMLButtonElement>('.history-refresh')!.click()
    await vi.waitFor(() => expect(dialog().textContent).toContain('offline'))
    expect(dialog().querySelectorAll('.history-row')).toHaveLength(3)
    dialog().querySelector<HTMLButtonElement>('.history-text-button')!.click()
    await vi.waitFor(() => expect(dialog().querySelector('.history-error')).toBeNull())
    expect(actions.refresh).toHaveBeenCalledTimes(2)
    expect(actions.remote).toHaveBeenCalledOnce()
  })
  it('shows the remote mainline first and explains the local base and builtin migration', async () => {
    await ready(); app.unmount()
    const newer = 'd'.repeat(40), rootSha = 'e'.repeat(40), migration = 'c'.repeat(64)
    actions.local.mockResolvedValue({ revision: sha, hasFork: true, commits: [
      { id: 'b'.repeat(64), parent: migration, upstreamRevision: sha, kind: 'update', createdAt: Date.parse('2026-11-02T03:00:00Z'), paths: ['references/study.md'] },
      { id: migration, parent: 'bundled:1', upstreamRevision: sha, kind: 'migrate', createdAt: Date.parse('2026-11-01T01:00:00Z'), paths: ['SKILL.md'] },
    ] })
    actions.revision.mockResolvedValue(newer)
    actions.remote.mockResolvedValue({ commits: [{ ...commit(newer), parents: [sha] }, { ...commit(sha), parents: [rootSha] }, { ...commit(rootSha), parents: [] }], hasMore: false })
    mount()
    await vi.waitFor(() => expect(dialog().querySelectorAll('.history-row')).toHaveLength(5))
    const entries = [...dialog().querySelectorAll<HTMLElement>('.history-entry')]
    expect(entries[0].dataset.source).toBe('github')
    for (const entry of entries) expect(entry.querySelector('svg circle')?.getAttribute('cx')).toBe(entry.dataset.source === 'github' ? '11' : '22')
    expect(dialog().querySelector('.is-head')!.textContent).toContain(`基准更新至 ${sha.slice(0, 7)}`)
    expect(dialog().textContent).not.toContain('更新上游并保留本地改动')
    expect(dialog().querySelector('.history-sync-note')!.textContent).toContain(`本地仍基于 ${sha.slice(0, 7)}`)
    expect(entries.find(entry => entry.textContent?.includes('本地基准'))?.dataset.source).toBe('github')
    entries.find(entry => entry.textContent?.includes('从内置版本导入'))!.querySelector<HTMLButtonElement>('button')!.focus()
    await nextTick()
    expect(dialog().querySelector('.history-hover')!.textContent).toContain('没有可关联的 GitHub 父提交')
  })
  it('shows delayed hover details without expanding rows and keeps them reachable across the pointer gap', async () => {
    await ready()
    const row = dialog().querySelector<HTMLButtonElement>('.history-row')!
    row.dispatchEvent(new Event('pointerenter'))
    expect(dialog().querySelector('.history-hover')).toBeNull()
    await vi.waitFor(() => expect(dialog().querySelector('.history-hover')).not.toBeNull())
    expect(dialog().querySelector('details')).toBeNull()
    expect(dialog().querySelector('.history-hover')!.textContent).toContain('b'.repeat(64))
    row.dispatchEvent(new Event('pointerleave'))
    dialog().querySelector('.history-hover')!.dispatchEvent(new Event('pointerenter'))
    await new Promise(resolve => setTimeout(resolve, 190))
    expect(dialog().querySelector('.history-hover')).not.toBeNull()
    dialog().querySelector('.history-hover')!.dispatchEvent(new Event('pointerleave'))
    await vi.waitFor(() => expect(dialog().querySelector('.history-hover')).toBeNull())
    row.dispatchEvent(new Event('pointerenter'))
    await vi.waitFor(() => expect(dialog().querySelector('.history-hover')).not.toBeNull())
    dialog().querySelector('.history-content')!.dispatchEvent(new Event('scroll')); await nextTick()
    expect(dialog().querySelector('.history-hover')).toBeNull()
  })
  it('navigates the merged rows and their hover actions with the keyboard', async () => {
    await ready()
    const rows = [...dialog().querySelectorAll<HTMLElement>('button.history-row')]
    rows[0].focus()
    rows[0].dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowDown', bubbles: true }))
    expect(document.activeElement).toBe(rows[1])
    rows[1].dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowDown', bubbles: true }))
    expect(document.activeElement).toBe(rows[2])
    rows[2].dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowRight', bubbles: true })); await nextTick()
    expect(document.activeElement).toBe(dialog().querySelector('.history-commit-link'))
    document.activeElement!.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true })); await nextTick()
    expect(document.activeElement).toBe(rows[2])
    expect(rows[2].classList.contains('is-selected')).toBe(true)
    expect(dialog().querySelector('.history-hover')).toBeNull()
    rows[2].dispatchEvent(new KeyboardEvent('keydown', { key: 'Home', bubbles: true }))
    expect(document.activeElement).toBe(rows[0])
  })
  it('keeps metadata out of the rows and explains the limits of historical checkpoints in the hover', async () => {
    await ready()
    const entries = dialog().querySelectorAll('.history-entry[data-source=local]')
    expect(entries[0].textContent).not.toContain('bbbbbbbb')
    expect(entries[0].textContent).not.toContain('SKILL.md')
    entries[0].querySelector<HTMLButtonElement>('button')!.focus(); await nextTick()
    expect(dialog().querySelector('.history-hover')!.textContent).toContain('SKILL.md')
    expect(dialog().querySelector('.history-hover')!.textContent).toContain('仅保存在本机')
    entries[1].querySelector<HTMLButtonElement>('button')!.focus(); await nextTick()
    expect(dialog().querySelector('.history-hover')!.textContent).toContain('此前的逐次修改未记录')
  })
  it('inserts paginated upstream events into the unified order and opens the actual commit safely', async () => {
    await ready(); app.unmount()
    actions.remote.mockResolvedValueOnce({ commits: [commit(sha)], hasMore: true }).mockResolvedValueOnce({ commits: [commit('d'.repeat(40), '2026-11-01T00:00:00Z')], hasMore: false })
    mount(); await ready()
    expect(dialog().querySelector('script')).toBeNull()
    dialog().querySelector<HTMLButtonElement>('.history-remote-commit button')!.focus(); await nextTick()
    dialog().querySelector<HTMLAnchorElement>('a')!.click()
    await vi.waitFor(() => expect(actions.open).toHaveBeenCalledWith(commit(sha).url))
    dialog().querySelector<HTMLButtonElement>('.history-more')!.click()
    await vi.waitFor(() => expect(dialog().querySelectorAll('.history-row')).toHaveLength(4))
    expect(actions.remote).toHaveBeenLastCalledWith('chaoxing.com', sha, 2)
    expect(dialog().querySelector('.history-entry:last-child')?.getAttribute('data-source')).toBe('github')
    expect(dialog().querySelector('.history-more')).toBeNull()
  })
  it('keeps local history visible offline and retries the same upstream page after failure', async () => {
    await ready(); app.unmount()
    actions.remote.mockRejectedValueOnce(new Error('offline'))
    mount()
    await vi.waitFor(() => expect(dialog().textContent).toContain('offline'))
    expect(dialog().querySelectorAll('.history-row')).toHaveLength(2)
    actions.remote.mockResolvedValueOnce({ commits: [commit(sha)], hasMore: false })
    dialog().querySelector<HTMLButtonElement>('.history-text-button')!.click()
    await ready()
    expect(actions.remote).toHaveBeenLastCalledWith('chaoxing.com', sha, 1)
  })
  it('keeps the default unified view for unmodified caches and marks the upstream as current', async () => {
    await ready(); app.unmount()
    actions.local.mockResolvedValue({ revision: sha, hasFork: false, commits: [] })
    mount()
    await vi.waitFor(() => expect(dialog().querySelectorAll('.history-row')).toHaveLength(1))
    expect(dialog().querySelector<HTMLInputElement>('.history-filter input:checked')!.value).toBe('all')
    expect(dialog().querySelector('.is-head')?.textContent).toContain('main')
    dialog().dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }))
    expect(close).toHaveBeenCalledOnce()
  })
})
